// tetris_flow.c - generated by split_c.py from tetris.c
#include "tetris_priv.h"



//*****************************************************************************
// 5. GAME FLOW
//*****************************************************************************

// Bring in the next piece at the top. Returns false if it does not fit.
bool tet_SpawnPiece(void)
{
    tet_cur.type = tet_nextType;
    tet_cur.rot  = 0;
    tet_cur.x    = 3;
    tet_cur.y    = 0;
    tet_nextType = tet_NextFromBag();
    tet_gravityCount = 0;

    return tet_Fits(tet_cur.type, tet_cur.rot, tet_cur.x, tet_cur.y);
}


void tet_TetrisShift(int16_t dir)
{
    if(tet_Fits(tet_cur.type, tet_cur.rot, tet_cur.x + dir, tet_cur.y)) tet_cur.x += dir;
}


// Rotate clockwise with a simple wall kick (try left, then right).
void tet_TetrisRotate(void)
{
    int16_t nr = (tet_cur.rot + 1) & 3;

    if(tet_Fits(tet_cur.type, nr, tet_cur.x, tet_cur.y))              tet_cur.rot = nr;
    else if(tet_Fits(tet_cur.type, nr, tet_cur.x - 1, tet_cur.y))   { tet_cur.rot = nr; tet_cur.x--; }
    else if(tet_Fits(tet_cur.type, nr, tet_cur.x + 1, tet_cur.y))   { tet_cur.rot = nr; tet_cur.x++; }
}


// Start a banner over the playfield.
void tet_ShowBanner(uint16_t kind)
{
    tet_bannerKind  = kind;
    tet_bannerTimer = TETRIS_BANNER_FRAMES;
    tet_bannerDirty = true;
    tet_bannerErase = false;
}


// Lock the piece. If any rows are full, START the flash (the rows are removed
// later by FinishClear(), and the next piece spawns then). Otherwise spawn now.
// Returns false if the next piece cannot spawn (game over).
bool tet_LockAndSpawn(void)
{
    tet_PlaceOnBoard(tet_cur.type, tet_cur.rot, tet_cur.x, tet_cur.y);

    tet_clearMask = tet_FindFullRows(&tet_clearCount);
    if(tet_clearMask)
    {
        tet_clearing   = true;
        tet_clearTimer = TETRIS_CLEAR_FRAMES;

        if(tet_clearCount == 4)
        {
            Buzzer_PlaySfx(&sfx_tetris_say);        // four rows = "TETRIS!"
            tet_ShowBanner(BANNER_TETRIS);
        }
        else
        {
            Buzzer_PlaySfx(&sfx_coin);              // 1-3 rows: chime
        }
        return true;                                // spawn happens in FinishClear()
    }

    Buzzer_PlaySfx(&sfx_thud);                      // optional: piece landed, no clear
    tet_score += 4;                                   // bonus for every piece locked
    return tet_SpawnPiece();
}


// The flash is over: remove the rows, score them, spawn the next piece.
// Returns false if the next piece cannot spawn (game over).
bool tet_FinishClear(void)
{
    int16_t cleared = tet_ClearFullRows();

    tet_score += (uint32_t)tet_lineScore[cleared] * (tet_level + 1);
    tet_lines += cleared;
    tet_level  = tet_lines / 10;
    if(tet_level > 9) tet_level = 9;                    // plenty fast by level 9
    tet_score += 4;                                   // bonus for every piece locked

    tet_clearing  = false;
    tet_clearMask = 0;
    return tet_SpawnPiece();
}
